import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const m=JSON.parse('{"title":"Current Membership Locks and Role Lifecycle","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/members","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/members.md","filePath":"en/tutorials/members.md"}'),r={name:"en/tutorials/members.md"};function n(o,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="current-membership-locks-and-role-lifecycle" tabindex="-1">Current Membership Locks and Role Lifecycle <a class="header-anchor" href="#current-membership-locks-and-role-lifecycle" aria-label="Permalink to &quot;Current Membership Locks and Role Lifecycle&quot;">​</a></h1><p>Goal: order business writes against member demotion/deactivation and reuse existing member management. Start with <a href="./sessions">Sessions</a> and resource authorization. A deployment serves one Organization.</p><p>Complete reference: <a href="./library-grants">resource authorization</a>.</p><h2 id="public-interfaces-and-usage" tabindex="-1">Public Interfaces and Usage <a class="header-anchor" href="#public-interfaces-and-usage" aria-label="Permalink to &quot;Public Interfaces and Usage&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a> provides <code>MemberRole::{Owner, Admin, Member}</code>, <code>active_role_in</code> and <code>lock_memberships</code>. Call them inside your business transaction; locks remain through commit/rollback. SQL excerpt:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> saas_core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">memberships</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> active</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SHARE</span></span></code></pre></div><p><code>None</code> means no active membership. Use <code>lock_memberships(&amp;mut tx, &amp;ids)</code> to lock multiple affected members in ID order before resources. Do not add unordered member locks after a resource lock. Signatures are in the authorization guide.</p><p>Complete reference: <a href="./library-grants">authorization guide</a>.</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a> exposes batch <code>profiles(connection, ids)</code> and transactional <code>revoke_user_sessions(connection, user_id)</code>. Use these instead of joining private credential tables or querying one profile at a time.</p><h2 id="reuse-the-management-api" tabindex="-1">Reuse the Management API <a class="header-anchor" href="#reuse-the-management-api" aria-label="Permalink to &quot;Reuse the Management API&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/management.rs" target="_blank" rel="noreferrer">Management Handlers/use cases</a> provide paginated members and <code>PUT /api/v1/organization/members/{user_id}</code> with <code>role / active / version</code>. Lists default to 50, maximum 100, with administrator-bound cursors; stale versions return 409. Owners manage Owners, Admins only non-Owners, and Members are denied.</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/domain.rs" target="_blank" rel="noreferrer">Pure rules</a> and transactions protect the last Owner. Lock the singleton Organization row, then actor/target memberships in ID order. Check active Owners, roles and version within the transaction; update membership, revoke needed Sessions, append Audit and commit. Never count outside the transaction and update separately.</p><p>Demoting/deactivating the last active Owner returns <code>422 organization.last_owner</code>. Two simultaneous Owner departures allow one success; initial registration uses the same coordination row.</p><h2 id="reactivation-does-not-restore-old-sessions" tabindex="-1">Reactivation Does Not Restore Old Sessions <a class="header-anchor" href="#reactivation-does-not-restore-old-sessions" aria-label="Permalink to &quot;Reactivation Does Not Restore Old Sessions&quot;">​</a></h2><p>Deactivation revokes all old Sessions, password-reset materials and appends Audit in the membership transaction. Old Cookies remain invalid after reactivation; users log in again. Session issuance holds the membership lock and orders consistently with deactivation. Audit failure rolls all changes back.</p><p>Business writes hold shared Membership locks and administration takes exclusive locks. A previously returned role, client dropdown or cached eligibility cannot replace current transactional checks. Independently managed API Keys check active status on each authentication; password reset does not automatically revoke them.</p><h2 id="verify-your-integration" tabindex="-1">Verify Your Integration <a class="header-anchor" href="#verify-your-integration" aria-label="Permalink to &quot;Verify Your Integration&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> members</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> membership_policy</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/api/tests/members.rs" target="_blank" rel="noreferrer">Real HTTP checks</a> cover roles, stale versions, concurrent last-Owner protection, Audit rollback, deactivation/reactivation and login races. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/membership_policy.rs" target="_blank" rel="noreferrer">Pure checks</a> cover the rule set. Add a controlled deactivation/write race for your business to prove legal commit ordering. Apply the discipline to <a href="./attachments">file completion</a> and <a href="./document-exports">background publication</a>.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/08-members.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,22)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
